-- # Lernfeld 5: Cyberphysische Systeme > ## IT-Sicherheit > - Sicherheit > - + Firewall

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann eine Firewall alle internen Bedrohungen innerhalb eines Netzwerks effektiv abwehren?', 2, '[{"text": "Nein", "correct": true, "because": "Interne Angriffe umgehen Perimeter-Schutz"}, {"text": "Ja", "correct": false, "because": "Firewall schützt primär extern"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Firewall in der Lage, verschlüsselte Datenpakete ohne zusätzliche Tools zu analysieren?', 2, '[{"text": "Nein", "correct": true, "because": "Verschlüsselung verhindert Inhaltsprüfung"}, {"text": "Ja", "correct": false, "because": "Nur mit DPI oder Entschlüsselung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können moderne Firewalls Bedrohungen auf Anwendungsebene erkennen und blockieren?', 2, '[{"text": "Ja", "correct": true, "because": "Next-Generation-Firewalls analysieren Anwendungen"}, {"text": "Nein", "correct": false, "because": "NGFW widerlegt dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Schützt eine Firewall automatisch vor allen Arten von DDoS-Angriffen?', 2, '[{"text": "Nein", "correct": true, "because": "Volumetrische Angriffe überlasten oft"}, {"text": "Ja", "correct": false, "because": "Begrenzte Kapazität"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Firewall ohne regelmäßige Updates ihre Schutzwirkung vollständig verlieren?', 2, '[{"text": "Ja", "correct": true, "because": "Neue Bedrohungen erfordern aktuelle Regeln"}, {"text": "Nein", "correct": false, "because": "Grundschutz bleibt teilweise"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Funktion einer Firewall ist entscheidend, um unerlaubten Zugriff zu verhindern?', 2, '[{"text": "Paketfilterung", "correct": true, "because": "Prüft Header nach Regeln"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht Firewall-Aufgabe"}, {"text": "Virenscan", "correct": false, "because": "Virenschutz-Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Firewall bietet die tiefste Analyse von Netzwerkverkehr?', 3, '[{"text": "Next-Generation Firewall", "correct": true, "because": "Integriert DPI und Anwendungserkennung"}, {"text": "Stateless Firewall", "correct": false, "because": "Nur grundlegende Filterung"}, {"text": "Proxy-Firewall", "correct": false, "because": "Fokus auf Vermittlung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird von einer Firewall typischerweise geprüft, um Datenverkehr zu steuern?', 2, '[{"text": "IP", "correct": true, "because": "Grundlage für Adressierung"}, {"text": "HTTP", "correct": false, "because": "Höhere Ebene"}, {"text": "DNS", "correct": false, "because": "Spezifische Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptschwäche einer einfachen paketfilternden Firewall?', 2, '[{"text": "Keine Zustandsprüfung", "correct": true, "because": "Stateless ignoriert Sitzungen"}, {"text": "Hoher Ressourcenverbrauch", "correct": false, "because": "Eher gering"}, {"text": "Fehlende Verschlüsselung", "correct": false, "because": "Nicht Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie erweitert eine Firewall am besten gegen komplexe Angriffe?', 2, '[{"text": "Intrusion Prevention System", "correct": true, "because": "Erkennt und blockt Anomalien"}, {"text": "Backup-Software", "correct": false, "because": "Nur Wiederherstellung"}, {"text": "Dateikomprimierung", "correct": false, "because": "Irrelevant"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften zeichnen eine Stateful Firewall aus?', 4, '[{"text": "Verfolgung von Verbindungszuständen", "correct": true, "because": "Prüft Sitzungen"}, {"text": "Analyse von Paketinhalten", "correct": false, "because": "NGFW-Funktion"}, {"text": "Filterung nach Port und IP", "correct": true, "because": "Grundfunktion"}, {"text": "Speicherung von Sitzungsdaten", "correct": true, "because": "Zustandstabelle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedrohungen kann eine Firewall gezielt abwehren?', 3, '[{"text": "Unautorisierter Zugriff", "correct": true, "because": "Filtert nach Regeln"}, {"text": "SQL-Injection", "correct": false, "because": "Anwendungsebene"}, {"text": "Port-Scanning", "correct": true, "because": "Blockiert unerlaubte Ports"}, {"text": "Malware-Verteilung", "correct": true, "because": "Mit IPS möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren erhöhen die Effektivität einer Firewall?', 3, '[{"text": "Aktuelle Regelsets", "correct": true, "because": "Passt Schutz an"}, {"text": "Integration mit IDS/IPS", "correct": true, "because": "Erweitert Erkennung"}, {"text": "Hohe Datenkomprimierung", "correct": false, "because": "Irrelevant"}, {"text": "Dynamische Anpassung", "correct": true, "because": "Reagiert auf Verkehr"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schwächen könnten eine Firewall unwirksam machen?', 4, '[{"text": "Fehlkonfiguration", "correct": true, "because": "Regeln ineffektiv"}, {"text": "Verschlüsselter Verkehr", "correct": true, "because": "Inhalt unprüfbar"}, {"text": "Langsame Updates", "correct": true, "because": "Neue Bedrohungen offen"}, {"text": "Geringe Bandbreite", "correct": false, "because": "Beeinflusst nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für eine moderne Firewall essenziell?', 3, '[{"text": "Paketfilter", "correct": true, "because": "Grundschutz"}, {"text": "Deep Packet Inspection", "correct": true, "because": "Tiefe Analyse"}, {"text": "Antivirus-Engine", "correct": false, "because": "Virenschutz-Funktion"}, {"text": "Protokollprüfung", "correct": true, "because": "Spezifische Steuerung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Eine Firewall kann Datenverkehr basierend auf Anwendungen filtern. b) Stateless Firewalls sind komplexer als Stateful Firewalls.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "NGFW filtert Anwendungen, Stateless einfacher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Firewalls schützen vor physischen Angriffen auf Hardware. b) Eine Firewall kann den Datenverkehr zwischen zwei internen Netzwerken steuern.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Physisch nicht möglich, intern steuerbar"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eine Proxy-Firewall arbeitet ausschließlich auf der Netzwerkschicht. b) Firewalls können durch VPN-Tunnel umgangen werden.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Proxy auf Anwendungsebene, VPN verschleiert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine Firewall kann ohne zusätzliche Software Malware erkennen. b) NGFW sind teurer als traditionelle Firewalls.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Malware braucht AV, NGFW komplexer"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Firewalls sind nutzlos gegen verschlüsselte Angriffe. b) Stateful Firewalls verfolgen keine Paketsequenzen.', 3, '[{"text": "Beides falsch", "correct": true, "because": "DPI hilft, Stateful verfolgt Sequenzen"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]');

